    margin-top: 0.4rem;
    font-size: 0.85rem;
    color: var(--text-secondary);
}

.error-message {
    margin-top: 0.4rem;
    font-size: 0.85rem;
    color: var(--error-color);
}

button[type="submit"] {
    background-color: var(--accent-color);
    color: #000;
    border: none;
    border-radius: 4px;
    padding: 0.75rem;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    width: 100%;
    transition: background-color 0.2s;
