 const { useState } = React;

 const FormField = ({ label, id, type = "text", required, autocomplete, helperText, value, onChange, error }) => {
     const helperId = `${id}-helper`;
     const errorId = `${id}-error`;
     const describedBy = [
         helperText ? helperId : null,
         error ? errorId : null
     ].filter(Boolean).join(' ');

     return (
         <div className="form-field">
             <label htmlFor={id}>
                 {label}
                 {required && <span className="required-mark" aria-hidden="true">*</span>}
             </label>
             <input
                 id={id}
                 name={id}
                 type={type}
                 required={required}
                 autoComplete={autocomplete}
                 value={value}
                 onChange={onChange}
                 aria-describedby={describedBy || undefined}
                 aria-invalid={!!error}
             />
             {helperText && (
                 <div id={helperId} className="helper-text">
                     {helperText}
                 </div>
             )}
             {error && (
                 <div id={errorId} className="error-message">
                     Error: {error}
                 </div>
             )}
         </div>
     );
 };

 const ContactForm = () => {
     const [formData, setFormData] = useState({
         fullName: "",
         email: "",
         phone: ""
     });
     const [errors, setErrors] = useState({});
     const [submitted, setSubmitted] = useState(false);

     const handleChange = (e) => {
         const { name, value } = e.target;
         setFormData(prev => ({
             ...prev,
             [name]: value
         }));
         // Clear error when user types
         if (errors[name]) {
             setErrors(prev => {
                 const newErrors = { ...prev };
                 delete newErrors[name];
                 return newErrors;
             });
         }
     };

     const handleSubmit = (e) => {
         e.preventDefault();

         // Basic validation
         const newErrors = {};
         if (!formData.fullName.trim()) newErrors.fullName = "Full name is required";
         if (!formData.email.trim()) newErrors.email = "Email address is required";

         if (Object.keys(newErrors).length > 0) {
             setErrors(newErrors);
             // Accessibility: Focus the first invalid field
             const firstErrorField = Object.keys(newErrors)[0];
             document.getElementById(firstErrorField).focus();
             return;
         }

         console.log("Form submitted:", formData);
         setSubmitted(true);
         // Reset form or show success message
     };

     if (submitted) {
         return (
             <div className="container" role="status">
                 <h1>Thank you!</h1>
                 <p>Your support request has been received. We'll get back to you shortly.</p>
                 <button onClick={() => setSubmitted(false)}>Send another message</button>
             </div>
         );
     }

     return (
         <div className="container">
             <h1>Contact Support</h1>
             <form onSubmit={handleSubmit} noValidate>
                 <FormField
                     label="Full Name"
                     id="fullName"
                     autocomplete="name"
                     required={true}
                     value={formData.fullName}
                     onChange={handleChange}
